/* ============================================================
 * ai_inference.c
 * ============================================================
 * Wraps the C code generated by STM32Cube AI Studio.
 *
 * IMPORTANT - after you generate code in STM32Cube AI Studio:
 *   1. Copy the generated files (typically network.h, network.c,
 *      network_data.h, network_data.c, and the ai_platform/*
 *      runtime files) into your project - STM32Cube AI Studio's
 *      "Generate code" step tells you exactly where they land,
 *      or copy them under Core/Inc and Core/Src / Middlewares.
 *   2. Confirm the generated network's handle type and function
 *      prefix - STM32Cube AI Studio names these after your model
 *      name (here assumed to be "network", matching the default).
 *      If you named your model differently in the tool, do a
 *      find-and-replace of "network" with your actual model name
 *      in this file.
 *   3. Add the generated folder(s) to your project's include paths
 *      in STM32CubeIDE (Project Properties -> C/C++ Build -> Settings
 *      -> Include Paths).
 * ============================================================ */

#include "ai_inference.h"
#include <string.h>
#include <math.h>

